\begin{theo}\label{th:ar-rpm}
Let $A=A(\X)$ be a $\sigma(\X)$-measurable random field on $\R^d$, where $\X$ is a completely independent random field on some measure space\linebreak$X=\biguplus_{x\in\Z^d}X_{x}$ with values in some measurable space $M$. For all $x\in\Z^d$, $\ell\in\N$, set $X_x^\ell:=\bigcup_{y\in\Z^d:|x-y|_\infty\le\ell}X_y$. Given an i.i.d. copy $\X'$ of the field $\X$, let the perturbed field $\X^{x,\ell}$ be defined by
\[
\X^{x,\ell}|_{X\setminus X_x^\ell}=\X|_{X\setminus X_x^\ell},\quad\text{and}\quad\X^{x,\ell}|_{X_x^\ell}=\X'|_{X_x^\ell},
\]
and assume that
\begin{enumerate}\alphenumi
\item \label{theo-2.8.1}For all $x,\ell$, there exists an action radius $\rho_x^\ell$ for $A$ wrt $\X$ in $X_x^\ell$, that is, a nonnegative random variable $\rho_x^\ell$ such that we have a.s.,
\[
A(\X^{x,\ell})|_{\R^d\setminus (Q_{2\ell+1}(x)+B_{\rho_x^\ell})}=A(\X)|_{\R^d\setminus (Q_{2\ell+1}(x)+B_{\rho_x^\ell})}.
\]
\item \label{theo-2.8.2}The transformation $A$ of $\X$ is stationary, that is, the random fields $A(\X\linebreak(\cdot+x,\cdot))$ and $A(\X)(\cdot+x)$ have the same law for all $x\in\Z^d$.
\item \label{theo-2.8.3}For all $x,\ell$, the random variable $\rho_x^\ell$ is $\sigma\Big(\X\big|_{X_x^{\ell+\rho_x^\ell}\setminus X_x^\ell}\Big)$-measurable.\footnote{This is understood as follows: for all $r\ge0$ the event $\{\rho_x^\ell>r\}$ belongs to $\sigma\Big(\X\big|_{X_x^{\ell+r}\setminus X_x^\ell}\Big)$.}
(In particular, for all $x,\ell,R$, given the event $\rho_x^\ell\le R$, the random variables $\rho_x^\ell$ and~$\rho_x^{\ell+R}$ are independent.)
\end{enumerate}
Assume that $R\ge1$ can be chosen large enough so that
\begin{align}\label{eq:choice-R}
\sup_{\ell\ge R}\,\prm{\rho_x^\ell\ge\ell}\le\tfrac14\,,
\end{align}
let $\pi_0:\R_+\to\R_+$ be a non-increasing function such that $\pr{\frac14\ell\le\rho_x^{\ell_0}<\ell}\le\pi_0(\ell)$ holds for all $0\le\ell_0\le\frac14\ell$, and define the weight 
\[
\pi(\ell):=(\ell+1)^{d}
\begin{cases}
\mkern70mu1,&\text{if }\ell\le 4R\,;\\8\ell^{-1}\pi_0(\frac12\ell),&\text{if }\ell>4R\,.
\end{cases}
\]
Then for all $\sigma(A)$-measurable random variables $Z(A)$ we have
\begin{align}
\var{Z(A)}&\le\frac12\,\expec{\int_0^\infty\int_{\R^d}{\Big(\oscd{A,B_{\sqrt d(\ell+1)}(x)}Z(A)\Big)^2}dx\,(\ell+1)^{-d}\pi(\ell) d\ell},\label{eq:AG-SG}
\\
\ent{Z(A)}&\le2\,\expec{\int_0^\infty\int_{\R^d}{\Big(\oscd{A,B_{\sqrt d(\ell+1)}(x)}Z(A)\Big)^2}dx\,(\ell+1)^{-d}\pi(\ell) d\ell}.\label{eq:AG-LSI}
\end{align}

\end{theo}

\begin{lem}\label{lem:spec-corr-zeta-1}
For all $n\ge0$ and $\xi\in \R^d$, we recursively define $\check\zeta^{n,0}_\xi\in H^1_{{\per}}(Q)$ as the unique periodic scalar field that satisfies
\begin{multline}\label{e.zeta0n}
-\nabla\cdot\Aa\nabla\check \zeta^{n,0}_\xi=\nabla\cdot(\Aa i\xi\check\zeta^{n-1,0}_\xi)
+i\xi\cdot\Aa\big(\nabla\check\zeta^{n-1,0}_\xi+i\xi\check\zeta^{n-2,0}_\xi\big)\\
-\check\psi^{n+1}_\xi+\sum_{k=0}^{n+1}\Bexpec{\overline{\check\psi^{n+1-k}_\xi}\check\psi^k_\xi},
\end{multline}
with integration constant\vspace*{-3pt}
\begin{equation}\label{eq:expec-zeta}
\expecm{\check \zeta^{n,0}_\xi}:=-\sum_{k=1}^{n}\sum_{l=2}^{k+2}(\overline{\check \lambda_\xi^l/\check \lambda_\xi^2})\,\Bexpec{\overline{\check\psi^{k+2-l}_\xi}\check\zeta^{n-k,0}_\xi}.
\end{equation}
With this choice of the constant, the above equation for $\check\zeta^{n,0}_\xi$ is indeed well-posed by the Fredholm alternative as it iteratively ensures that the right-hand side has vanishing average,\vspace*{-3pt}
\begin{equation}\label{eq:chocolate}
\expec{i\xi\cdot\Aa\big(\nabla\check\zeta^{n-1,0}_\xi+i\xi\check\zeta^{n-2,0}_\xi\big)}+\sum_{k=0}^{n+1}\expec{\overline{\check\psi^{n+1-k}_\xi}\check\psi^k_\xi}=0.
\end{equation}
{Factoring out powers of $i\xi$,} we may then define the real-valued symmetric tensor field~$\zeta^{n,0}$ such that\vspace*{-3pt}
\[\zeta^{n,0} \odot (i\xi)^{\otimes (n+1)}:= \check\zeta^{n,0}_{\xi}.\qedhere\]
\end{lem}

\begin{lem}[A priori estimates]\label{lem:apriori}
Let $\Lc$ be a self-adjoint operator on $\Ld^2(\R^d)$ satisfying the bound $-\triangle\le\Lc\le-C_0\triangle$ for some constant $C_0<\infty$. Given
$F_1\in\Ld^1_\loc(\R^+;\Ld^2(\R^d))$ and $F_2,F_3\in W^{1,1}_\loc(\R^+;\Ld^2(\R^d))$ with $F_2|_{t=0}=F_3|_{t=0}=0$, let $z$ be the solution of the wave equation
\begin{equation*}
\begin{cases}
(\partial_t^2+\Lc) z=F_1+\nabla \cdot F_2+\partial_t F_3\quad\text{in $\R^d$},\\
z|_{t=0}=\partial_t z|_{t=0}=0.
\end{cases}
\end{equation*}
Then, for all $t\ge 0$, we have
\[\|z^t\|_{\Ld^2(\R^d)}\,\lesssim_{C_0}\,t\|F_1\|_{\Ld^1((0,t);\Ld^2(\R^d))}+\|(F_2,F_3)\|_{\Ld^1((0,t);\Ld^2(\R^d))},\]
and
\[\|Dz^t\|_{\Ld^2(\R^d)} \,\lesssim_{C_0}\,\|(F_1,\partial_tF_2,\partial_tF_3)\|_{\Ld^1((0,t);\Ld^2(\R^d))}.\qedhere\]
\end{lem}

\begin{lem}\label{lem:approx-dt2g1-gaus}
Consider the Gaussian setting~\eqref{eq:Gaussian}.
For all $\sigma<\frac12$, there exist $\delta,s>0$
such that
\begin{equation*}
\sup_{0\le t\le N^\sigma}\Big\|N\partial_t^2g_N^{1;t}-iS_{N,\beta}^{1,+}e^{-it(\Id\otimes T_\beta)}iS_{N,\beta}^{2,-}(\tfrac1{\mu_\beta}f^\circ)\Big\|_{H^{-s}_\beta(\R^2)}\,\lesssim_\sigma\,N^{-\delta}.
\end{equation*}
\end{lem}

\begin{lem}[Global hierarchical estimates]\label{lem:hier}
Given $T\in(0,\infty]$, let $\{a_n\}_{n\ge1}$ be a sequence of continuous maps $a_n:[0,T)\to\R^+$ satisfying the following hierarchy of differential inequalities for some parameters~$A,R\ge1$: for all $n\ge1$,
\begin{equation}\label{eq:ineq-an}
\left\{\begin{array}{ll}
\tfrac{d}{dt}a_n\,\le\,
n(a_n+a_{n+1})
+n^3R^{-2}(a_{n-1}+a_{n-2}),&\text{on $[0,T)$},\\[1mm]
a_n(0)\le n^{2n}(AR^{-1} )^n.&
\end{array}\right.
\end{equation}
Further assume the following a priori estimates for some $B\ge1$: for all $n\ge1$ and $t\in[0,T)$,
\begin{equation}\label{eq:apriori-an}
a_n(t)\le B^n.
\end{equation}
Then there is a constant $C\ge1$ (only depending on $B$, and not on~$T,A,R$) such that we have for all~$n\ge1$ and~$t\in[0,T)$,
\begin{equation}\label{eq:todo-an}
a_n(t)\le e^{Cnt}(Cn^2)^n(AR^{-1})^n.
\end{equation}
\end{lem}
